import heapq
def delay(n, edges, k):
    g = {}
    for u, v, w in edges: g.setdefault(u, []).append((v, w))
    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[k] = 0
    pq = [(0, k)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]: continue
        for v, w in g.get(u, []):
            nd = d + w
            if nd < dist[v]: dist[v] = nd; heapq.heappush(pq, (nd, v))
    m = max(dist.values())
    return m if m != float('inf') else -1
